const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-117.3, 32.84]); // Point offshore La Jolla, CA
  const date2018 = ee.Date('2018-08-01');
  const date2017 = ee.Date('2017-08-01');
  const dataset = 'NOAA/CDR/OISST/V2.1';
  const band = 'sst';

  // Function to get temperature for a given date
  const getTemperature = function(date) {
    const collection = ee.ImageCollection(dataset)
      .filterDate(date, date.advance(1, 'day'))
      .select(band);

    const size = collection.size().getInfo();
    if (size === 0) {
      return { temp: null, size: 0, pixels: 0 };
    }

    const image = collection.first();
    // Raw value is scaled by 0.01 to get degrees C.
    const scaledImage = image.multiply(0.01);

    const stats = scaledImage.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: point,
      scale: 1000,
      maxPixels: 1e9
    });

    const temp = stats.get(band + '_mean').getInfo();
    const pixelCount = stats.get(band + '_count').getInfo();

    return { temp: temp, size: size, pixels: pixelCount };
  };

  // 2. Data Acquisition & Processing
  const data2018 = getTemperature(date2018);
  const data2017 = getTemperature(date2017);

  // 3. Validation & Final Answer
  console.log(`2018-08-01: Images found: ${data2018.size}, Pixels processed: ${data2018.pixels}`);
  console.log(`2017-08-01: Images found: ${data2017.size}, Pixels processed: ${data2017.pixels}`);

  if (data2018.size === 0 || data2017.size === 0) {
    console.log("Evidence: Could not find an image for one or both dates.");
    console.log("C1");
    return;
  }

  if (data2018.pixels === 0 || data2017.pixels === 0) {
    console.log("Evidence: Found images but no valid pixels in the region of interest.");
    console.log("C2");
    return;
  }

  const temp2018 = data2018.temp;
  const temp2017 = data2017.temp;

  if (temp2018 === null || temp2017 === null) {
    console.log(`Evidence: Failed to calculate temperature. 2018: ${temp2018}, 2017: ${temp2017}`);
    console.log("C3");
    return;
  }

  console.log(`Evidence: 2018 Sea Surface Temp (C): ${temp2018.toFixed(2)}`);
  console.log(`Evidence: 2017 Sea Surface Temp (C): ${temp2017.toFixed(2)}`);

  if (temp2018 > temp2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

